body_clean:
Version: Deno 1.43.6

```js
import http from "";
http
  .createServer((req, res) => { res.end("hello") })
  .listen("/tmp/test.sock")
```

```sh
file /tmp/test.sock # No such file or directory
```
The path is in `NormalizedArgs`, just missing from the `serve` options:

```diff
diff --git a/ext/node/polyfills/http.ts b/ext/node/polyfills/http.ts
index 6b862ce83..05882a8d5 100644
--- a/ext/node/polyfills/http.ts
+++ b/ext/node/polyfills/http.ts
@@ -1656,10 +1656,10 @@ export class ServerImpl extends EventEmitter {
     if (hostname == "localhost") {
       hostname = "127.0.0.1";
     }
-    this.#addr = {
+    this.#addr = options.path ? { path: options.path } : {
       hostname,
       port,
-    } as Deno.NetAddr;
+    };
     this.listening = true;
     nextTick(() => this._serve());
```

```sh
file /tmp/test.sock # socket
curl --unix-socket /tmp/test.sock http://test # "hello"
```

