Steps to reproduce:
1. Create two pages with FAB. One of them is opening from another one.
2. Make any button on the second page which calls the async function on tap; this function hides the FAB for a while, shows it and pops the page.
3. The operation must be not longer than the FAB animation duration (let's take 100ms).

Expected results:
The second page hides, the first page has emerging FAB (since heroTags are equal).

Actual results:
The second page hides, the first page doesn't show its FAB because of the error: `There are multiple heroes that share the same tag within a subtree.`

Code sample:
Code sample

```dart
import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';

void main()
{
  runApp(const MyApp());
}

class MyApp extends StatelessWidget
{
  const MyApp({ super.key });

  @override
  Widget build(final BuildContext context)
  {
    return MaterialApp(
      routes: {
        '/page1': (context) => const Page1(),
        '/page2': (context) => const Page2(),
      },
      initialRoute: '/page1',
    );
  }
}

class Page1 extends StatelessWidget
{
... [truncated] ...

class _Page2State extends State<Page2>
{
  @override
  Widget build(final BuildContext context)
  {
    return Scaffold(
      appBar: AppBar(title: const Text('Page2')),
      body: Center(
        child: OutlinedButton(
          onPressed: () async {
            setState(() => _processing = true);
            await Future.delayed(const Duration(milliseconds: 100));
            setState(() => _processing = false);
            SchedulerBinding.instance.addPostFrameCallback((_) {
              if (context.mounted) Navigator.of(context).pop();
            });
          },
          child: const Text('Do async op'),
        )
      ),
      floatingActionButton: _processing ? null : FloatingActionButton(
        key: const ValueKey(2),
        onPressed: () {},
        child: const Icon(Icons.add),
      ),
    );
  }

  bool _pr
```

